  `id` int(11) NOT NULL AUTO_INCREMENT,
  `min_price` int(11) NOT NULL COMMENT '最小抓取价格',
  `max_price` int(10) NOT NULL COMMENT '最大抓取价格',
  `sessionid` varchar(255) NOT NULL DEFAULT '',
  `parallelism` int(11) NOT NULL DEFAULT '1' COMMENT '队列数量',
  `delay` int(11) NOT NULL,
