  `steam_price_cny` decimal(10,2) unsigned NOT NULL,
  `quick_price` decimal(10,2) unsigned NOT NULL,
  `sell_min_price` decimal(10,2) unsigned NOT NULL,
  `sell_num` int(10) unsigned NOT NULL,
  `sell_reference_price` decimal(10,2) unsigned NOT NULL,
  `steam_market_url` varchar(255) NOT NULL DEFAULT '',
  `transacted_num` int(10) unsigned NOT NULL,
