  `updated_at` int(11) unsigned NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `id` (`id`) USING BTREE,
  UNIQUE KEY `goods_id` (`goods_id`) USING BTREE,
  KEY `name` (`name`),
  KEY `nam2` (`market_hash_name`),
  KEY `steam_item_name_id` (`steam_item_name_id`) USING BTREE
